def solution(input_data):
    import sys
    from collections import defaultdict

    input_lines = input_data.strip().split('\n')
    n, m = map(int, input_lines[0].split())

    offers = []
    for i in range(1, m + 1):
        l, r = map(int, input_lines[i].split())
        offers.append((l, r))

    results = []

    # For each x from 1 to n
    for x in range(1, n + 1):
        occupied = [False] * (n + 2)  # 1-indexed, with padding
        total_days = 0

        for l, r in offers:
            # Check condition 1: length >= x
            if r - l + 1 < x:
                continue

            # Check condition 2: all days in [l, r] are free
            all_free = True
            for day in range(l, r + 1):
                if occupied[day]:
                    all_free = False
                    break

            if all_free:
                for day in range(l, r + 1):
                    occupied[day] = True
                total_days += (r - l + 1)

        results.append(str(total_days))

    return '\n'.join(results) + '\n'

