def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse events
    events = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        if parts[0] == '1':
            events.append(('1',))
        else:
            events.append(('2', parts[1]))

    # Collect batches between type 1 events
    batches = []
    current_batch = []
    for i in range(len(events)):
        if events[i][0] == '1':
            if current_batch:
                # Convert to set of friend names
                batch_friends = {name for _, name in current_batch}
                batches.append(batch_friends)
                current_batch = []
            # Start new batch next
        else:
            current_batch.append(events[i])
    # Don't forget the last batch
    if current_batch:
        batch_friends = {name for _, name in current_batch}
        batches.append(batch_friends)

    # If there are no batches, no one can be happy
    if not batches:
        return '0'

    # Build conflict graph
    # Two friends are connected if they appear in the same batch
    # This means they cannot both be happy
    from collections import defaultdict

    # Map each friend to a unique integer
    friend_map = {name: i for i, name in enumerate(sorted(set(name for batch in batches for name in batch)))}
    total_friends = len(friend_map)

    # Adjacency matrix for conflict graph
    conflict = [[False] * total_friends for _ in range(total_friends)]

    for batch in batches:
        friends_in_batch = list(batch)
        for i in range(len(friends_in_batch)):
            for j in range(i + 1, len(friends_in_batch)):
                idx_i = friend_map[friends_in_batch[i]]
                idx_j = friend_map[friends_in_batch[j]]
                conflict[idx_i][idx_j] = conflict[idx_j][idx_i] = True

    # Find maximum independent set using bitmask (since m <= 40, but limited by actual friend count)
    # Optimization: only consider friends that actually appear in batches

    # For efficiency, use recursion with pruning
    best = 0

    def solve(options, mask):
        nonlocal best
        # Pruning: if remaining nodes can't beat best, return
        if len(options) + best <= best:
            return

        # If no options left, we're done
        if not options:
            best = max(best, mask.bit_count())
            return

        # Take the first option
        pick = options[0]
        remaining_options = options[1:]

        # Option 1: don't pick this node
        solve(remaining_options, mask)

        # Option 2: pick this node (can only do this if not conflicting with any already selected)
        conflicts_with = i for i in range(len(remaining_options))
        if conflict[pick][conflicts_with]:
            continue

        if not any(conflict[pick][c] for c in used):
            new_mask = mask | (1 << pick)
            new_used = used | {pick}
            solve(remaining_options, new_mask)

    # Actual implementation with better complexity
    best = [0]
    available = list(range(total_friends))

    def dfs(idx, mask):
        nonlocal best[0]

        if idx == len(available):
            best[0] = max(best[0], mask.bit_count())
            return

        friend = available[idx]

        # Option 1: Don't include this friend
        dfs(idx + 1, mask)

        # Option 2: Include this friend (if it doesn't conflict with already in mask)
        can_pick = True
        for other in available[:idx]:
            mask2 = 0
            for j in range(idx):
                if available[j] == other:
                    mask2 = mask2 | (1 << other)
                    break

        for i in range(idx):
            if mask & (1 << available[i]):
                if conflict[friend][available[i]]:
                    can_pick = False

        if can_pick:
            dfs(idx + 1, mask | (1 << friend))

    dfs(0, 0)
    return str(best[0])
