def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append({'u': u, 'v': v, 'w': w, 'idx': i})

    # If m == n-1, all edges are in MST, return empty
    if m == n - 1:
        return ''

    # Kruskal's algorithm to build MST
    sorted_edges = sorted(edges, key=lambda x: x['w'])
    parent = list(range(n + 1))

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i, root_j = find(i), find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    mst_indices = set()
    for edge in sorted_edges:
        if union(edge['u'], edge['v']):
            mst_indices.add(edge['idx'])

    # Build MST adjacency list
    mst_adj = [[] for _ in range(n + 1)]
    for edge in edges:
        if edge['idx'] in mst_indices:
            mst_adj[edge['u']].append((edge['v'], edge['w']))
            mst_adj[edge['v']].append((edge['u'], edge['w']))

    # Binary lifting for LCA and max edge on path
    LOG = n.bit_length()
    if LOG == 0:
        LOG = 1
    up = [[0] * (LOG + 1) for _ in range(n + 1)]
    maxw = [[0] * (LOG + 1) for _ in range(n + 1)]
    depth = [0] * (n + 1)

    # BFS from node 1 to compute depths and build binary lifting table
    queue = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while queue:
        u = queue.pop(0)
        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                up[v][0] = u
                maxw[v][0] = w
                queue.append(v)

    # Build binary lifting table
    for j in range(1, LOG + 1):
        for i in range(1, n + 1):
            up[i][j] = up[up[i][j - 1]][j - 1]
            maxw[i][j] = max(maxw[i][j - 1], maxw[up[i][j - 1]][j - 1])

    def query_max_on_path(u, v):
        """Returns max weight edge on path between u and v in MST"""
        if u == v:
            return 0

        result = 0

        if depth[u] < depth[v]:
            u, v = v, u

        # Lift u to same depth as v
        diff = depth[u] - depth[v]
        for j in range(LOG, -1, -1):
            if diff & (1 << j):
                result = max(result, maxw[u][j])
                u = up[u][j]

        if u != v:
            for j in range(LOG, -1, -1):
                if up[u][j] != up[v][j]:
                    result = max(result, maxw[u][j])
                    result = max(result, maxw[v][j])
                    u = up[u][j]
                    v = up[v][j]

        if u != v:
            result = max(result, maxw[u][0])
            result = max(result, maxw[v][0])

        return result

    # For each non-MST edge, find max weight on path in MST
    output = []
    for edge in edges:
        if edge['idx'] not in mst_indices:
            mx = query_max_on_path(edge['u'], edge['v'])
            output.append(str(mx))

    return '\n'.join(output)

