def solution(input_str):
    """
    Find the longest common subsequence of s1 and s2 that does not contain virus as a substring.

    Uses dynamic programming with KMP state tracking to ensure virus substring is never formed.
    """
    lines = input_str.strip().split('\n')
    s1, s2, virus = lines[0], lines[1], lines[2]
    m, n, k = len(s1), len(s2), len(virus)

    if not s1 or not s2:
        return '0'

    # KMP failure function (lps array)
    pi = [0] * k
    for i in range(1, k):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Function to compute next virus match state after adding character c
    def compute_next_state(v, char):
        while v > 0 and char != virus[v]:
            v = pi[v-1]
        if char == virus[v]:
            v += 1
        return v

    INF = -float('inf')
    # dp[i][j][v] = maximum LCS length using s1[:i], s2[:j] with virus matched prefix of length v
    dp = [[[INF] * (k + 1) for _ in range(n + 1)] for _ in range(m + 1)]
    # parent[i][j][v] stores the previous state to reconstruct the solution
    parent = [[[(-1, -1, -1)] * (k + 1) for _ in range(n + 1)] for _ in range(m + 1)]

    dp[0][0][0] = 0

    for i in range(m):
        for j in range(n):
            for v in range(k + 1):
                if dp[i][j][v] == INF:
                    continue

                # Option 1: If characters match, we can potentially include this character
                if s1[i] == s2[j]:
                    next_v = compute_next_state(v, s1[i])

                    if next_v < k:
                        # Adding this character doesn't complete the virus
                        if dp[i+1][j+1][next_v] < dp[i][j][v] + 1:
                            dp[i+1][j+1][next_v] = dp[i][j][v] + 1
                            parent[i+1][j+1][next_v] = (i, j, v)
                    else:
                        # Adding this character would complete the virus - skip s1[i]
                        if dp[i+1][j][v] < dp[i][j][v]:
                            dp[i+1][j][v] = dp[i][j][v]
                            parent[i+1][j][v] = (i, j, v)
                        if dp[i][j+1][v] < dp[i][j][v]:
                            dp[i][j+1][v] = dp[i][j][v]
                            parent[i][j+1][v] = (i, j, v)

                # Option 2: Skip characters (when mismatch or to skip virus-completing char)
                if dp[i][j][v] < dp[i+1][j][v]:
                    dp[i+1][j][v] = dp[i][j][v]
                    parent[i+1][j][v] = (i, j, v)

                if dp[i][j][v] < dp[i][j+1][v]:
                    dp[i][j+1][v] = dp[i][j][v]
                    parent[i][j+1][v] = (i, j, v)

    # Find the maximum value at the end across all valid virus states
    max_len, best_v = -1, 0
    for v in range(k + 1):
        if v < k and dp[m][n][v] > max_len:
            max_len = dp[m][n][v]
            best_v = v

    if max_len <= 0:
        return '0'

    # Backtrack to reconstruct the LCS
    res = []
    i, j, v = m, n, best_v

    while i > 0:
        curr_parent = parent[i][j][v]
        if curr_parent[0] == -1:
            return '0'

        p_i, p_j, p_v = curr_parent

        if p_i == i - 1 and p_j == j - 1:
            # Characters matched at this position
            res.append(s1[i-1])
            v = p_v
        else:
            # Skipped character, just update pointers
            i = p_i
            j = p_j
            v = p_v

        i = p_i
        j = p_j

    return ''.join(res[::-1])


