def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(m):
        a, b = map(int, lines[1 + i].split())
        edges.append((a, b))

    # Check if two edges cross: (a,b) and (c,d) cross if they are interleaved
    def cross(a, b, c, d, n):
        # Normalize so we work clockwise
        if a > b:
            a, b = b, a
        if c > d:
            c, d = d, c

        # If any edge equals another (same endpoints), no crossing
        if a == c and b == d:
            return False
        if a == d and b == c:
            return False

        # Check if c and d split the arc defined by a and b
        # They cross if c is between a and b, AND d is between b and a
        # Going clockwise from a to b

        def between(x, start, end):
            # check if x is on clockwise arc from start to end (exclusive)
            return (start < x < end) or (start >= end and (start <= x or x <= end))

        c_between_ab = between(c, a, b)
        d_between_ab = between(d, a, b)

        return c_between_ab != d_between_ab

    # Build graph for 2-SAT
    # Node 2*i = edge i inside, Node 2*i+1 = edge i outside
    # Total nodes: 2*m
    # We use implication graph with 2*m nodes

    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]

    # For each pair of crossing edges, we need (li XOR lj)
    # That is: (li implies lj') and (lj implies li')
    # and also: (li' implies lj) and (lj' implies li)
    # where li' is NOT li
    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i][0], edges[i][1], edges[j][0], edges[j][1], n):
                # Edge i inside (2*i) implies edge j outside (2*j+1)
                adj[2 * i].append(2 * j + 1)
                # Edge i outside (2*i+1) implies edge j inside (2*j)
                adj[2 * i + 1].append(2 * j)
                # Edge j inside (2*j) implies edge i outside (2*i+1)
                adj[2 * j].append(2 * i + 1)
                # Edge j outside (2*j+1) implies edge i inside (2*i)
                adj[2 * j + 1].append(2 * i)

    # Build reverse graph
    r_adj = [[] for _ in range(num_nodes)]
    for u in range(num_nodes):
        for v in adj[u]:
            r_adj[v].append(u)

    # Find SCCs using Kosaraju's algorithm
    visited = [False] * num_nodes
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * num_nodes
    visited = [False] * num_nodes
    num_scc = 0

    def dfs2(u, c):
        visited[u] = True
        comp[u] = c
        for v in r_adj[u]:
            if not visited[v]:
                dfs2(v, c)

    for i in reversed(order):
        if not visited[i]:
            dfs2(i, num_scc)
            num_scc += 1

    # Check if any variable and its negation are in same SCC
    for i in range(m):
        if comp[2 * i] == comp[2 * i + 1]:
            return "Impossible\n"

    # Find satisfying assignment
    # For each pair (2*i, 2*i+1), pick the one in the lower-numbered SCC
    # (since in topological order, we want to pick true for nodes before their negation)
    assignment = [0] * m
    for i in range(m):
        if comp[2 * i] <= comp[2 * i + 1]:
            assignment[i] = 0  # inside
        else:
            assignment[i] = 1  # outside

    return ''.join(['i' if x == 0 else 'o' for x in assignment]) + '\n'


