    n, k = map(int, lines[0].split())
    s = lines[1]

    # dp[pos][diff] = can we reach state (pos, diff)?
    # diff = wins - loses
    # Valid diff range: -(k-1) to (k-1) at all intermediate positions

    from functools import lru_cache

    # Use LRU cache for memoization
    @lru_cache(maxsize=None)
    def can_solve(pos, diff):
        # Check if difference is within valid bounds
        if abs(diff) >= k:
            return False

        # Base case: reached end
        if pos == n:
            # Only valid if we reached exactly k difference
            return abs(diff) == k

        # Try all possible outcomes
        outcomes = ['W', 'L', 'D']
        for outcome in outcomes:
            if s[pos] == '?' or s[pos] == outcome:
                # Calculate new difference
                new_diff = diff
                if outcome == 'W':
                    new_diff += 1
                elif outcome == 'L':
                    new_diff -= 1
                # D doesn't change diff

                # Check bounds before recursive call
                if abs(new_diff) < k:
                    if can_solve(pos + 1, new_diff):
                        return True

        return False

    # Start from position 0 with difference 0
    if can_solve(0, 0):
        # Reconstruct the solution by backtracking
        result = [''] * n
        pos, diff = 0, 0

        while pos < n and abs(diff) < k:
            for outcome in ['W', 'L', 'D']:
                if result[pos] != '':
                    continue

                if s[pos] == '?' or s[pos] == outcome:
                    new_diff = diff
                    if outcome == 'W':
                        new_diff += 1
                    elif outcome == 'L':
                        new_diff -= 1

                    if abs(new_diff) < k and can_solve(pos + 1, new_diff):
                        result[pos] = outcome
                        diff = new_diff
                        pos += 1
                        break

        # Verify the final state
        if abs(diff) == k and pos == n:
            return ''.join(result) + '\n'
        else:
            return 'NO\n'

    return 'NO\n'

