def solution(input_string):
    if not input_string or not input_string.strip():
        return "0\n"

    lines = input_string.strip().split('\n')
    first_line = lines[0].strip()
    if not first_line:
        return "0\n"

    n, m = map(int, first_line.split())

    adj = [[] for _ in range(n + 1)]
    edge_list = []

    for i in range(m):
        # Handle lines by index starting from 1 (after header)
        if 1 + i < len(lines):
            line = lines[1 + i].strip()
            if line:
                u, v = map(int, line.split())
                edge_list.append((u, v))
                adj[u].append((v, i))
                adj[v].append((u, i))

    if m == 0:
        if n == 1:
            return "\n"
        else:
            return "0\n"

    # Find bridges using DFS
    discovery = {}
    low = {}
    timer = [0]
    bridge_edges = set()

    def dfs_bridges(u, p):
        nonlocal timer
        discovery[u] = low[u] = timer[0]
        timer[0] += 1

        for v, idx in adj[u]:
            if v == p:
                continue

            if v in discovery:
                # Back edge
                low[u] = min(low[u], discovery[v])
            else:
                # Tree edge
                dfs_bridges(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > discovery[u]:
                    # Edge (u, v) is a bridge
                    bridge_edges.add(idx)

    dfs_bridges(1, -1)

    # Check if any edges are bridges
    for i in range(m):
        if i in bridge_edges:
            return "0\n"

    # Build orientation using DFS
    # Tree edges: parent -> child
    # Back edges: descendant -> ancestor (if v discovered before u)
    result = [None] * m
    visited = set()

    def dfs_orient(u, p):
        visited.add(u)
        for v, idx in adj[u]:
            if idx == p:  # Skip the edge we came from in DFS tree
                continue

            if v not in visited:
                # This is a tree edge: orient u -> v
                result[idx] = (u, v)
                dfs_orient(v, -1)
            else:
                # This is a back edge or cross edge: orient based on discovery time
                # By standard DFS, all back edges go to ancestors
                if discovery.get(v, 0) <= discovery.get(u, 0):
                    result[idx] = (u, v)
                else:
                    result[idx] = (v, u)

    # Ensure all edges are oriented - traverse all components
    for start_node in range(1, n + 1):
        if start_node not in visited:
            dfs_orient(start_node, -1)

    # Verify we have all edges oriented
    oriented = sum(1 for r in result if r is not None)
    if oriented != m:
        return "0\n"

    # Verify strong connectivity with BFS
    final_adj = [[] for _ in range(n + 1)]
    for u, v in result:
        final_adj[u].append(v)

    # BFS from node 1
    visited_bfs = [False] * (n + 1)
    queue = deque([1])
    visited_bfs[1] = True
    count = 1

    while queue:
        u = queue.popleft()
        for v in final_adj[u]:
            if not visited_bfs[v]:
                visited_bfs[v] = True
                count += 1
                queue.append(v)

    if count != n:
        return "0\n"

    # Return results
    lines_out = []
    for u, v in result:
        lines_out.append(f"{u} {v}")
    return "\n".join(lines_out) + "\n"


