def count_distinct(a):
    dp = [0] * (len(a) + 1)
    dp[0] = 1
    last = {}
    for i in range(len(a)):
        dp[i + 1] = 2 * dp[i]
        if a[i] in last:
            dp[i + 1] -= dp[last[a[i]]]
        last[a[i]] = i
    return dp[len(a)]

def brute_force(n, m):
    from itertools import product
    total = 0
    for seq in product(range(m), repeat=n):
        total += count_distinct(list(seq))
    return total

