    if best is None:
        return None

    return best[0]


def generate_win_patterns(wins_a, total):
    """Generate all patterns of wins for given count"""
    from itertools import combinations
    if wins_a == 0:
        return [0] * total
    elif wins_a == total:
        return [1] * total
    else:
        indices = range(total)
        patterns = []
        for combo in combinations(indices, wins_a):
            pattern = [0] * total
            for i in combo:
                pattern[i] = 1
            patterns.append(pattern)
        return patterns


