def solution(data: str) -> str:
    import sys
    from collections import defaultdict

    lines = data.strip().split('\n')
    n, k = map(int, lines[0].split())

    phone_numbers = {}
    for i in range(1, n + 1):
        parts = lines[i].split()
        s = parts[0]
        m = int(parts[1])
        phone_numbers[s] = m

    # Collect all unique prefixes from all phone numbers
    all_prefixes = set()
    for s in phone_numbers:
        for i in range(1, len(s) + 1):
            all_prefixes.add(s[:i])

    # Store which phone numbers start with each prefix
    prefix_nums = defaultdict(list)
    for s, m in phone_numbers.items():
        for i in range(1, len(s) + 1):
            prefix = s[:i]
            prefix_nums[prefix].append((s, m, i))  # (number_str, m, len)

    # Initialize L_max for each phone number
    # Store as {s: current_max_prefix_length}
    l_max = {s: 0 for s in phone_numbers}

    # Greedy approach: select k best prefixes
    selected_prefixes = set()

    # We need to perform k iterations
    for _ in range(k):
        best_gain = 0
        best_prefix = None

        for prefix in all_prefixes:
            if prefix in selected_prefixes:
                continue

            # Calculate marginal gain for this prefix
            # It's |P| * sum of m_i for all phone numbers starting with P 
            # AND whose L_max < |P|
            current_gain = 0
            for (s, m, _) in prefix_nums[prefix]:
                if l_max[s] < len(prefix):
                    current_gain += m * len(prefix)

            if current_gain > best_gain:
                best_gain = current_gain
                best_prefix = prefix

        if best_prefix is None:
            # No improvement possible, stop early
            break

        selected_prefixes.add(best_prefix)

        # Update L_max for affected phone numbers
        for (s, m, _) in prefix_nums[best_prefix]:
            if l_max[s] < len(best_prefix):
                l_max[s] = len(best_prefix)

    # Calculate final cost
    total_cost = 0
    for s, m in phone_numbers.items():
        cost = (len(s) - l_max[s]) * m
        total_cost += cost

    return str(total_cost)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, t = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    x = list(map(int, lines[2].split()))

    # Check basic constraints
    for i in range(n):
        if x[i] > n: return "No\n"

    # Compute x constraints
    # For each position p, find min a_i + t where x_i < p (upper bound)
    # Find max a_i + t where x_i == p (lower bound)

    lb = [1] * (n + 1)  # 1-indexed, lb[p] is lower bound for b_p
    ub = [float('inf')] * (n + 1)  # upper bound, could be inf

    for i in range(n):
        needs = a[i] + t
        if x[i] < len(lb):
            lb[x[i]] = max(lb[x[i]], needs)
        if x[i] + 1 <= len(lb):
            ub[x[i] + 1] = min(ub[x[i] + 1], needs)

    # Build b array
    b = []
    curr = 1

    for p in range(1, n + 1):
        curr = max(curr + 1, lb[p])  # enforce strictly increasing
        if curr >= ub[p]:
            return "No\n"
        b.append(curr)

    # Additional validation
    for i in range(n):
        if b[x[i] - 1] < a[i] + t:
            return "No\n"
        for p in range(x[i], n):
            if b[p] >= a[i] + t:
                return "No\n"

    return f"Yes\n{' '.join(map(str, b))}\n"

