def solution(input_str):
    MOD = 1051131

    lines = input_str.strip().split('\n')
    m, t, s = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    n = 1 << m

    # Generate remaining a values if needed
    if len(a) < n:
        while len(a) < n:
            a.append((101 * a[-1] + 10007) % MOD)
    a = a[:n]

    def mat_vec_mul(v, M):
        """Computes v * M for row vector v"""
        return [sum(v[j] * M[j][i] for j in range(n)) % MOD for i in range(n)]

    def mat_mul(A, B):
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        A = [[x % MOD for x in row] for row in A]
        while p > 0:
            if p & 1:
                result = mat_mul(result, A)
            A = mat_mul(A, A)
            p >>= 1
        return result

    # Build matrix M where M[i][j] = 2^(number of common bits in i and j) if i|j and i!=j
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and j % i == 0:
                common = bin(i & j).count('1')
                M[i][j] = 1 << common
                M[i][j] %= MOD  # May exceed MOD

    if t == 0:
        final = [0] * n
        for i in range(n):
            final[i] = a[i]
    else:
        M_t = mat_pow(M, t - 1)
        final = mat_vec_mul(a, M_t)
        # Add self-terms: stay at 1 each day
        for i in range(n):
            final[i] = (final[i] + a[i]) % MOD

    result = 0
    for x in final:
        result ^= x

    return str(result) + '\n'

