    for i in range(1, len(lines)):
        try:
            n_values.append(int(lines[i]))
        except:
            break

    if not n_values:
        return ''

    max_n = max(n_values)

    # Precompute Fibonacci numbers up to max_n
    fib = [1, 2]
    while fib[-1] < max_n:
        fib.append(fib[-1] + fib[-2])

    # Memoization for count_ways across all queries
    memo = {}

    # Iterative DP to avoid recursion depth issues
    def get_count(n):
        if n == 0:
            return 1
        if n in memo:
            return memo[n]

        # Use DP: dp[j] = number of ways to make sum j
        dp = {0: 1}

        for f in fib:
            if f > n:
                break
            # Create new sums by adding f to existing sums
            new_sums = {}
            for s, count in dp.items():
                if s + f <= n:
                    if s + f not in new_sums:
                        new_sums[s + f] = count
                    else:
                        new_sums[s + f] += count
            dp.update(new_sums)

        result = dp.get(n, 0)
        memo[n] = result
        return result

    results = [str(get_count(n)) for n in n_values]
    return '\n'.join(results) + '\n'


